char sClass='B';
switch (sClass) {
case 'B’:   case 'b':
System.out.printf("Battleship\n");
break;
case 'C’:  case 'c':
System.out.printf("Cruiser\n");
break;
case 'D’:   case 'd':
System.out.printf("Destroyer\n");
break;
case 'F’:    case 'f':
System.out.printf("Frigate\n");
break;
default:
System.out.printf("Unknown ship class %c\n", sClass);
break;
}

